  const snap=p.live_snapshot||{},h=snap.historical_evidence||((snap.historical_pool_reconstruction)?snap:null),obs=h?.observed||{},fee=h?.fee_evidence||{},amt=h?.entry_amounts||{},fin=h?.financial_evidence||{},acct=p.accounting||{};
