    const hodl=acct.lp_vs_hodl_usd!=null?`${Number(acct.lp_vs_hodl_usd)>=0?'+':''}${money(acct.lp_vs_hodl_usd)}`:'Pending opening inventory';
    const dc=state?.money?.display_currency||'USD';stats=[[live?`Current LP value (${dc})`:'Last recorded value',money(p.current_value)],[live?`Tracked fees (${dc})`:'Unclaimed fees',money(earned||0)],[live?'Observed fee APR':'Historical APR field',pace],[live?'P/L incl. fees · vs HODL':'Recorded economics',`${pnl} · ${hodl}`]];
