async function calculateTargets(){const s=state.summary||{},rate=Number($('#target-rate').value||0),capital=Number(s.capital_deployed||0);if(capital<=0){$('#target-result').innerHTML='<div class="empty-state">No deployed LP capital yet. Monthly target tracking starts as soon as a live/imported position has a usable capital basis.</div>';return}const r=await api('/api/targets/calculate',{method:'POST',body:JSON.stringify({capital,target_monthly_pct:rate,actual_today:Number(s.fees_today||0),actual_7d:Number(s.fees_7d||0),actual_30d:Number(s.fees_30d||0)})});$('#target-result').innerHTML=[['Today',r.today],['7 days',r.week],['30 days',r.month]].map(([n,x])=>`<div class="metric"><div class="label">${n}</div><div class="value">${money(x.actual)} / ${money(x.target)}</div><div class="sub">${pct(x.attainment_pct,0)} · ${esc(x.status)}</div></div>`).join('')}
function openPositionModal(){modal(`<h2>Prepare new LP position</h2><p>Records strategy intent only. Signing and broadcast remain blocked.</p><div class="form-grid"><div class="field"><label>Pair</label><input id="op-pair" value="WETH/USDC"></div><div class="field"><label>Chain</label><select id="op-chain"><option>BASE</option><option>ETHEREUM</option><option>ARBITRUM</option><option>OPTIMISM</option><option>POLYGON</option><option>ROBINHOOD_CHAIN</option></select></div><div class="field"><label>Sleeve</label><select id="op-sleeve"><option value="CORE_INCOME">Core income</option><option value="TACTICAL_CAMPAIGN">Tactical campaign</option></select></div><div class="field"><label>Lower</label><input id="op-low" type="number" step="any"></div><div class="field"><label>Upper</label><input id="op-high" type="number" step="any"></div><div class="field"><label>Capital</label><input id="op-cap" type="number" value="1000"></div><div class="field"><label>Fee tier</label><input id="op-fee" type="number" placeholder="3000"></div></div><div class="actions"><button class="btn" id="op-submit">Prepare</button></div><div id="op-result" class="lower"></div>`);$('#op-submit').onclick=async()=>{try{const sleeve=$('#op-sleeve').value,r=await api('/api/open/prepare',{method:'POST',body:JSON.stringify({pair:$('#op-pair').value,chain:$('#op-chain').value,strategy_sleeve:sleeve,directional_bias:'NEUTRAL',inventory_intent:sleeve==='CORE_INCOME'?'ALLOW_ACCUMULATE_RISK_ASSET_ON_DOWNSIDE':'BALANCED',target_hold_days:sleeve==='CORE_INCOME'?30:3,lower_price:Number($('#op-low').value),upper_price:Number($('#op-high').value),capital_value:Number($('#op-cap').value),fee_tier:$('#op-fee').value?Number($('#op-fee').value):null,protocol:'UNISWAP_V3'})});$('#op-result').innerHTML=`<div class="list-card"><b>Build-only intent prepared</b><p>No funds moved.</p><div class="tag-row">${badge(r.status||'DRAFT')}${badge(r.mode||'build_only')}</div></div>`}catch(e){toast(e.message)}}}

async function runPortfolioAdvisor(){
  const target=$('#advisor-result');
  target.innerHTML='<div class="empty-state">Comparing current opportunities across chains…</div>';
  try{
    const capital=Number($('#advisor-capital').value||0), reserve=Number($('#advisor-reserve').value||10);
    const r=await api('/api/portfolio-advisor',{method:'POST',timeoutMs:120000,body:JSON.stringify({available_capital:capital,reserve_pct:reserve,max_positions:4,sleeve_filter:$('#advisor-sleeve').value,allocation_mode:$('#advisor-mode').value})});
    const rows=r.allocations||[], near=r.near_misses||[];
    if(rows.length){
      const cards=rows.map(x=>`<div class="allocation-row"><b>#${x.rank}</b><span><b>${esc(x.pair)}</b><div class="meta">${esc(x.chain)} · ${short(x.pool_address)}</div></span><span>${badge(x.sleeve,x.sleeve==='CORE_INCOME'?'core':'tactical')}</span><b>${money(x.amount)}</b><span><b>${money(x.expected_net_month)}</b><div class="meta">${pct(x.expected_net_month_pct||0)} · ${esc(x.economics_confidence||'')}</div></span><span>${num(x.score,0)}/100</span><button class="btn secondary small" onclick="openAdvisorStrategy('${esc(x.chain)}','${esc(x.pool_address)}','${esc(x.sleeve)}',${Number(x.amount)||0})">Strategy</button></div>`).join('');
      target.innerHTML=`<div class="allocation-summary"><b>${esc(r.allocation_mode||'DIVERSIFIED')} · ${esc(r.sleeve_filter||'ANY')}</b><span>Allocated ${money(r.allocated)} · reserve ${money(r.reserve_floor||0)} · unallocated ${money(r.unallocated||0)}</span></div><div class="allocation-row header"><span>Rank</span><span>Opportunity</span><span>Sleeve</span><span>Allocate</span><span>Operating net/mo</span><span>Score</span><span></span></div>${cards}<p class="meta">${esc(r.guardrail||'')} ${r.unallocated_reason?`· ${esc(r.unallocated_reason)}`:''}</p>${r.ai_advice?renderBrief(r.ai_advice):''}`;
    }else{
      const investigateCapital=Math.max(100,capital*(1-reserve/100));
      const nearHtml=near.map((x,i)=>`<div class="allocation-row"><b>#${i+1}</b><span><b>${esc(x.pair)}</b><div class="meta">${esc(x.chain)}</div></span><span>${badge(x.sleeve,x.sleeve==='CORE_INCOME'?'core':'tactical')}</span><span>${money(x.operating_net_month||0)}/mo</span><span>${num(x.score,0)}/100</span><span class="meta">${esc((x.reject_reasons||[]).join(' · '))}</span><button class="btn secondary small" onclick="openAdvisorStrategy('${esc(x.chain)}','${esc(x.pool_address)}','${esc(x.sleeve)}',${investigateCapital})">Strategy</button></div>`).join('');
      target.innerHTML=`<div class="warning-box"><b>No allocation yet.</b> ${esc(r.reason||'No candidate currently clears the guardrails.')}</div>${near.length?`<h3>Closest candidates — investigate rather than ignore</h3>${nearHtml}`:''}${r.ai_advice?renderBrief(r.ai_advice):''}`;
    }
    if((r.scan_errors||[]).length)target.innerHTML+=`<div class="warning-box lower">Some chains could not be freshly compared: ${(r.scan_errors||[]).map(x=>`${esc(x.chain)} (${esc(x.error)})`).join(' · ')}</div>`;
    await refresh();
  }catch(e){target.innerHTML=`<div class="warning-box">${esc(e.message)}</div>`}
}

