async function loadExecutionPool(silent=false){const chain=$('#exec-chain').value,address=$('#exec-pool').value.trim();if(!address){if(!silent)toast('Enter a pool address');return}if(!silent)$('#exec-pool-info').innerHTML='<div class="empty-state">Reading pool directly from chain…</div>';const fresh=await api(`/api/execution/pool/${encodeURIComponent(chain)}/${encodeURIComponent(address)}`,{timeoutMs:60000});const previousTick=Number(execPoolMeta?.current_tick);execPoolMeta=fresh;const t0=fresh.token0||{},t1=fresh.token1||{},lens=fresh.price_lens||{};$('#exec-live-price').textContent=`LIVE ${priceNum(lens.current)} ${unitLabel(lens.unit)}`;$('#exec-live-price').className='status-chip good';if(!silent){$('#exec-lower-label').textContent=`Lower range (${unitLabel(lens.unit)})`;$('#exec-upper-label').textContent=`Upper range (${unitLabel(lens.unit)})`;$('#exec-amount0-label').textContent=`${t0.symbol||'Token 0'} amount`;$('#exec-amount1-label').textContent=`${t1.symbol||'Token 1'} amount`;$('#exec-pool-info').innerHTML=`<div class="modal-grid">${info('Pair',`${esc(t0.symbol||'?')} / ${esc(t1.symbol||'?')}`)}${info('Fee tier',`${num(fresh.fee_tier_bps||0,2)} bps`)}${info('Current pool price',`<span id="exec-pool-price">${priceNum(lens.current)} ${esc(unitLabel(lens.unit))}</span>`)}${info('Current tick',`<span id="exec-pool-tick">${num(fresh.current_tick,0)}</span>`)}${info('Tick spacing',num(fresh.tick_spacing,0))}${info('Pool',short(fresh.pool_address))}</div>`}else{const price=$('#exec-pool-price'),tick=$('#exec-pool-tick');if(price)price.textContent=`${priceNum(lens.current)} ${unitLabel(lens.unit)}`;if(tick)tick.textContent=num(fresh.current_tick,0)}const hasAmount=Number($('#exec-amount0').value||0)>0||Number($('#exec-amount1').value||0)>0;if(hasAmount&&(!silent||Date.now()-execLastRequoteAt>=15000))scheduleExecutionQuote(silent?100:50);if(!silent&&document.querySelector('#execution-section.active'))setExecutionLiveMode(true);return fresh}
function scheduleExecutionQuote(delay=350){clearTimeout(execQuoteTimer);execQuoteTimer=setTimeout(()=>quoteExecutionAmounts().catch(e=>{const chip=$('#exec-live-price');if(chip){chip.textContent='Quote error';chip.className='status-chip warn'}console.warn(e)}),delay)}
async function quoteExecutionAmounts(){if(execQuoteBusy||!execPoolMeta)return;const lower=Number($('#exec-lower').value),upper=Number($('#exec-upper').value),known=execLastEditedSide===1?1:0,amount=Number((known===0?$('#exec-amount0'):$('#exec-amount1')).value||0);if(!(lower>0&&upper>lower&&amount>0))return;execQuoteBusy=true;try{const q=await api('/api/execution/open/quote',{method:'POST',timeoutMs:30000,body:JSON.stringify({chain:$('#exec-chain').value,pool_address:$('#exec-pool').value.trim(),lower_price:lower,upper_price:upper,known_side:known,known_amount:amount})});const quoted=q.quote||q;if(known===0)$('#exec-amount1').value=Number(quoted.amount1||0).toPrecision(10);else $('#exec-amount0').value=Number(quoted.amount0||0).toPrecision(10);execLastRequoteAt=Date.now();const chip=$('#exec-live-price');if(chip){chip.textContent=`LIVE ${priceNum(execPoolMeta?.price_lens?.current)} · paired`;chip.className='status-chip good'}}finally{execQuoteBusy=false}}
function setExecutionLiveMode(on){clearInterval(execPriceTimer);execPriceTimer=null;if(!on)return;if(execPoolMeta&&$('#exec-pool').value.trim())execPriceTimer=setInterval(()=>loadExecutionPool(true).catch(()=>{}),5000)}
function walletProviderChoices(){
  const out=[]; const seen=new Set();
  const add=(provider,info={})=>{if(!provider||seen.has(provider))return;seen.add(provider);const rdns=String(info.rdns||'').toLowerCase();const name=info.name||(provider.isCoinbaseWallet?'Coinbase Wallet':provider.isMetaMask?'MetaMask':'Browser EVM wallet');out.push({provider,info,name,rdns,preferred:rdns.includes('metamask')||(provider.isMetaMask&&!provider.isCoinbaseWallet)});};
  announcedWalletProviders.forEach(x=>add(x.provider,x.info||{}));
  (window.ethereum?.providers||[]).forEach(p=>add(p,{}));
  if(window.ethereum)add(window.ethereum,{});
  return out.sort((a,b)=>(Number(b.preferred)-Number(a.preferred))||a.name.localeCompare(b.name));
}
function bindChosenProvider(provider){
  if(!provider)return; provider.on?.('accountsChanged',a=>{browserWallet=a?.[0]||null;updateWalletChip()}); provider.on?.('chainChanged',()=>{if(document.querySelector('#execution-section.active'))loadExecutionPool(true).catch(()=>{})});
}
function getBrowserProvider(){return browserProvider||null}
function updateWalletChip(message=null,kind=null){const chip=$('#execution-wallet-chip');if(!chip)return;if(message){chip.textContent=message;chip.className=`status-chip ${kind||'warn'}`;return}chip.textContent=browserWallet?`Wallet ${short(browserWallet)}`:'Wallet not connected';chip.className=`status-chip ${browserWallet?'good':'warn'}`}
async function chooseBrowserProvider(){
  const choices=walletProviderChoices();
  if(!choices.length)return null;
  return await new Promise(resolve=>{
    modal('<div class="card-head"><div><h2>Choose browser wallet</h2><p class="meta">LP Manager will only use the wallet you explicitly select for human-confirmed signing.</p></div></div><div id="wallet-provider-list" class="lower">'+choices.map((x,i)=>'<button class="btn '+(x.preferred?'':'secondary')+' wallet-provider-choice" data-provider="'+i+'">'+esc(x.name)+(x.preferred?' · preferred':'')+'</button>').join(' ')+'</div>');
    $$('.wallet-provider-choice').forEach(btn=>btn.onclick=()=>{const picked=choices[Number(btn.dataset.provider)];browserProvider=picked?.provider||null;bindChosenProvider(browserProvider);closeModal();resolve(browserProvider)});
    $('#modal-close').onclick=()=>{closeModal();resolve(null)};
  });
}
async function detectBrowserWallet(){
  const provider=getBrowserProvider();
  if(!provider){const n=walletProviderChoices().length;updateWalletChip(n?`${n} wallet${n===1?'':'s'} detected · choose Connect`:'No browser wallet detected',n?'good':'warn');return}
  try{const a=await provider.request({method:'eth_accounts'});browserWallet=a?.[0]||null;updateWalletChip()}catch(e){updateWalletChip('Selected wallet unavailable','warn')}
}
async function buildExecutionPlan(){if(!execPoolMeta)await loadExecutionPool();const body={chain:$('#exec-chain').value,pool_address:$('#exec-pool').value.trim(),lower_price:Number($('#exec-lower').value),upper_price:Number($('#exec-upper').value),amount0:Number($('#exec-amount0').value||0),amount1:Number($('#exec-amount1').value||0),wrap_native_amount:Number($('#exec-wrap').value||0),slippage_bps:Number($('#exec-slippage').value||100),ttl_seconds:1200};$('#exec-build-result').innerHTML='<div class="empty-state">Building exact calls and simulating where possible…</div>';try{execPlan=await api('/api/execution/open/build',{method:'POST',timeoutMs:90000,body:JSON.stringify(body)});renderExecutionPlan()}catch(e){execPlan=null;$('#exec-build-result').innerHTML=`<div class="warning-box">${esc(e.message)}</div>`}}
function callSummary(call){if(!call)return '';return `<div class="execution-call"><div><b>${esc(call.purpose||'CONTRACT CALL')}</b><div class="meta">to ${short(call.to)} · value ${esc(call.value||'0x0')}</div></div></div>`}
function renderExecutionPlan(){if(!execPlan)return;const p=execPlan,sim=p.simulation||{},calls=[...(p.wrap_call?[p.wrap_call]:[]),...(p.approval_calls||[]),p.mint_call].filter(Boolean);$('#exec-build-result').innerHTML=`<div class="notice ${sim.ok?'good':'warn'}"><b>${esc(sim.status||'PREPARED')}</b> · server-side signing OFF · browser wallet required.</div><div class="modal-grid lower">${info('Range',`${priceNum(p.display_range?.lower)} → ${priceNum(p.display_range?.upper)} ${esc(unitLabel(p.display_range?.unit))}`)}${info('Ticks',`${p.ticks?.lower} → ${p.ticks?.upper}`)}${info('Token 0',`${priceNum(p.amounts?.token0)} ${(p.pool?.token0||{}).symbol||''}`)}${info('Token 1',`${priceNum(p.amounts?.token1)} ${(p.pool?.token1||{}).symbol||''}`)}${info('Simulation',sim.ok?'PASSED':esc(sim.status||'FAILED'))}${info('Gas estimate',p.gas_estimate?Number(p.gas_estimate).toLocaleString():'after prerequisites')}</div><div class="execution-calls lower">${calls.map(callSummary).join('')}</div>${sim.error?`<div class="warning-box">Simulation: ${esc(sim.error)}</div>`:''}`;const sign=$('#exec-sign-area');const prereqs=[...(p.wrap_call?[{kind:'wrap',call:p.wrap_call}]:[]),...(p.approval_calls||[]).map((c,i)=>({kind:`approval:${i}`,call:c}))];sign.innerHTML=prereqs.length?`<p><b>Prerequisites first.</b> Sign one call at a time, wait for confirmation, then rebuild so LP Manager can simulate the final mint against fresh allowances/balances.</p>${prereqs.map(x=>`<button class="btn secondary exec-send" data-call-kind="${x.kind}">Sign ${esc(x.call.purpose)}</button>`).join(' ')}`:sim.ok?`<div class="notice good"><b>Mint simulation passed.</b> Review everything above before signing.</div><button class="btn exec-send" data-call-kind="mint">Sign mint in browser wallet</button>`:`<div class="warning-box">Mint is not signable because simulation has not passed.</div>`;$$('.exec-send').forEach(b=>b.onclick=()=>sendExecutionCall(b.dataset.callKind).catch(e=>toast(e.message)))}
async function connectBrowserWallet(){const provider=await chooseBrowserProvider();if(!provider){const n=walletProviderChoices().length;updateWalletChip(n?'Wallet selection cancelled':'No browser wallet detected','warn');if(!n)toast('No injected EVM wallet was detected. Enable site access in your wallet extension, then refresh.');return}try{const accounts=await provider.request({method:'eth_requestAccounts'});browserWallet=accounts?.[0]||null;updateWalletChip();toast(browserWallet?'Browser wallet connected':'Wallet returned no account')}catch(e){updateWalletChip('Wallet connection rejected','warn');throw new Error(e?.message||'Browser wallet connection failed')}}
async function switchExecutionChain(){const provider=getBrowserProvider();if(!provider)throw new Error('Browser wallet unavailable');const cfg=(state.live?.chains||[]).find(x=>x.key===$('#exec-chain').value);const id=cfg?.chain_id;if(!id)throw new Error('Chain id unavailable');try{await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+Number(id).toString(16)}]})}catch(e){if(e?.code===4902)throw new Error('This chain is not configured in your browser wallet. Add it in MetaMask first, then retry.');throw e}}
async function waitReceipt(hash){const provider=getBrowserProvider();if(!provider)throw new Error('Browser wallet unavailable');for(let i=0;i<60;i++){const r=await provider.request({method:'eth_getTransactionReceipt',params:[hash]});if(r)return r;await new Promise(res=>setTimeout(res,2000))}throw new Error('Transaction submitted but receipt was not seen within 2 minutes. Check the wallet/explorer before retrying.')}
async function sendExecutionCall(kind){if(!$('#exec-confirm').checked)throw new Error('Tick the confirmation box after reviewing range, token amounts and calls.');const provider=getBrowserProvider();if(!provider)throw new Error('Connect a browser wallet first.');if(!browserWallet)await connectBrowserWallet();await switchExecutionChain();let call;if(kind==='mint'){if(!execPlan?.simulation?.ok)throw new Error('Mint simulation has not passed. Rebuild after prerequisites.');call=execPlan.mint_call}else if(kind==='wrap')call=execPlan?.wrap_call;else if(kind.startsWith('approval:'))call=(execPlan?.approval_calls||[])[Number(kind.split(':')[1])];if(!call)throw new Error('Prepared call is missing or stale. Rebuild the plan.');if(browserWallet&&state.wallet?.wallet&&browserWallet.toLowerCase()!==String(state.wallet.wallet).toLowerCase())throw new Error(`Connected browser wallet ${short(browserWallet)} is not the configured LP Manager wallet ${short(state.wallet.wallet)}.`);const tx={from:browserWallet,to:call.to,data:call.data,value:call.value||'0x0'};const hash=await provider.request({method:'eth_sendTransaction',params:[tx]});toast(`Submitted ${call.purpose||kind}: ${short(hash)}`);const receipt=await waitReceipt(hash);if(String(receipt.status).toLowerCase()!=='0x1')throw new Error('Transaction receipt indicates failure.');toast(`${call.purpose||kind} confirmed. Rebuilding live plan…`);await refreshWallet();await buildExecutionPlan()}
